#!/usr/bin/env python3
"""Finalize the reviewed Stage 09 on the laptop. Local files/Git only; zero PPO."""
import argparse
import base64
from datetime import datetime, timezone
import hashlib
import json
from pathlib import Path
import subprocess
import tempfile
import uuid
import zipfile
import zlib

REPO = Path('/home/lx/microduck-double-balance/workspace')
STAGE = REPO.parent / 'artifacts/double-balance-stage09'
RETURNED = STAGE / 'returned-pilot-20261001'
VIDEO = STAGE / 'video-review/20260930T210037Z-5a95cdc3'
BASE = '66ff9c3055ec6b9caa99c308b5aa5170655c6f5c'
ORIGIN = 'git@github.com:liuxue-lab/microduck-double-balance.git'
TAG = 'stage-09-complete'
MESSAGE = 'Finalize Stage 09 pilot review and balance-first handoff'
SCRIPT_REL = 'scripts/stage09_finalize_local.py'
LOCAL_REL = 'docs/audits/stage-09-local-finalization.json'
RUNTIME_SHA = 'b61850afbd6fa0deccb3a23a098a910aae74bc0e9b01cca2ee0634c2d1f6ecfd'
PRIMARY = '86d55c3703c18fcf4817db49c6e4dcf839b3f5195d68ae2c559db7e222bded97'
VIDEO_SHA = '8c342528ded3581441983eeff3caebdb69e496715caac38519f55a6c3e733369'
PAYLOAD = ''


def require(ok, message):
    if not ok:
        raise RuntimeError(message)


def sha(path):
    digest = hashlib.sha256()
    with Path(path).open('rb') as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b''):
            digest.update(chunk)
    return digest.hexdigest()


def read(path):
    return json.loads(Path(path).read_text(encoding='utf-8'))


def inside(root, relative):
    relative = Path(relative)
    require(not relative.is_absolute() and '..' not in relative.parts, 'Unsafe path: ' + str(relative))
    path = root / relative
    require(not path.is_symlink() and path.resolve().is_relative_to(root.resolve()), 'Unsafe link: ' + str(path))
    return path


def checked(path, checksum, size=None):
    path = Path(path)
    require(path.is_file() and not path.is_symlink(), 'Missing or linked file: ' + str(path))
    require(size is None or path.stat().st_size == size, 'Size mismatch: ' + str(path))
    require(sha(path) == checksum, 'SHA256 mismatch: ' + str(path))
    return path


def atomic(path, data):
    path.parent.mkdir(parents=True, exist_ok=True)
    mode = path.stat().st_mode & 0o777 if path.exists() else 0o644
    with tempfile.NamedTemporaryFile(dir=path.parent, delete=False) as out:
        temp = Path(out.name)
        out.write(data)
        out.flush()
    try:
        temp.chmod(mode)
        temp.replace(path)
    finally:
        temp.unlink(missing_ok=True)


def encoded(value):
    return (json.dumps(value, indent=2, ensure_ascii=False) + '\n').encode()


def git(*args):
    return subprocess.check_output(['git', '-C', str(REPO), *args], text=True).strip()


def git_paths(*args):
    raw = subprocess.check_output(['git', '-C', str(REPO), *args, '-z'])
    return {x.decode() for x in raw.split(b'\0') if x}


def tagged_commit():
    result = subprocess.run(['git', '-C', str(REPO), 'show-ref', '--verify', '--quiet', 'refs/tags/' + TAG])
    if result.returncode == 1:
        return None
    require(result.returncode == 0, 'Cannot read local tag')
    require(git('cat-file', '-t', 'refs/tags/' + TAG) == 'tag', 'Existing tag is not annotated; preserved')
    return git('rev-parse', 'refs/tags/' + TAG + '^{commit}')


def runtime():
    path = checked(REPO / 'docs/audits/stage-09-runtime-hashes.json', RUNTIME_SHA)
    rows = read(path)
    require(len(rows) == 101, 'Unexpected frozen runtime count')
    for relative, checksum in rows.items():
        checked(inside(REPO, relative), checksum)
    return rows


def verify_manifest(root, checksum, count):
    rows = read(checked(root / 'review-files.json', checksum))
    require(len(rows) == count and len({r['path'] for r in rows}) == count, 'Unexpected manifest count')
    for row in rows:
        checked(inside(root, row['path']), row['sha256'], row['size_bytes'])
    return rows


def verify_evidence(evidence):
    runtime()
    print('Stage09FrozenRuntimeUnchanged=101', flush=True)
    receipt = read(checked(RETURNED / 'return-verified.json', evidence['return_receipt_sha256']))
    require(receipt == evidence['return_receipt'], 'Unexpected return receipt')
    for row in receipt['checkpoints']:
        path = checked(inside(RETURNED, row['path']), row['sha256'], row['size_bytes'])
        info = read(checked(path.with_suffix('.json'), row['receipt_sha256'], row['receipt_size_bytes']))
        require(info['campaign_id'] == receipt['campaign_id'] and info['sha256'] == row['sha256']
                and info['profile'] == row['profile'] and info['experiment_completed_updates'] == row['updates'],
                'Checkpoint receipt mismatch: ' + str(path))
    require(len(receipt['checkpoints']) == 13, 'Expected 13 checkpoints')
    print('Stage09CheckpointRecheck=13/13', flush=True)
    verify_manifest(RETURNED / 'pilot', evidence['pilot_manifest_sha256'], 341)
    campaign = read(RETURNED / 'pilot/campaign.json')
    require(campaign['status'] == 'PILOT_COMPLETE_NO_ELIGIBLE_CANDIDATE'
            and campaign['campaign_id'] == receipt['campaign_id'], 'Campaign state differs')
    refs = campaign['evaluations']
    require(len(refs) == 18, 'Expected 18 cloud evaluation reports')
    cloud = Path('/root/autodl-tmp/microduck-double-balance/artifacts/double-balance-stage09')
    for reference in refs.values():
        report = read(checked(inside(RETURNED, Path(reference['path']).relative_to(cloud)), reference['sha256']))
        require(report['status'] == 'PASS', 'Incomplete original evaluation')
    print('Stage09CloudReportsRecheck=18/18', flush=True)
    video_rows = verify_manifest(VIDEO, evidence['video_manifest_sha256'], 175)
    checked(VIDEO.with_suffix('.zip'), VIDEO_SHA)
    with zipfile.ZipFile(VIDEO.with_suffix('.zip')) as archive:
        require(len(archive.namelist()) == 176 and len(set(archive.namelist())) == 176, 'Unexpected video archive members')
        require(set(archive.namelist()) == {r['path'] for r in video_rows} | {'review-files.json'}, 'Video archive inventory differs')
        require(hashlib.sha256(archive.read('review-files.json')).hexdigest() == evidence['video_manifest_sha256'],
                'Video archive manifest differs')
    run = read(VIDEO / 'video-run.json')
    require(run['new_ppo_updates'] == 0 and len(run['jobs']) == 10
            and run['status'] == 'LOCAL_VIDEO_GENERATION_COMPLETE_REVIEW_PENDING', 'Unexpected producer run')
    for job in run['jobs']:
        folder = inside(VIDEO, job['name'])
        checked(folder / ('env-' + str(job['env_id']) + '.mp4'), job['video_sha256'])
        checked(folder / 'evaluation.json', job['report_sha256'])
    print('Stage09VideoRecheck=10/10; ReviewFiles=175/175', flush=True)
    old = read(REPO / 'docs/audits/stage-08-return-verified.json')
    primary = Path(old['extracted_directory']) / 'extension/E-20260929/segment-001/checkpoints/update_004000.pt'
    checked(primary, PRIMARY)
    print('Stage09RetainedPrimarySHA256=PASS', flush=True)
    return dict(status='LOCAL_ARCHIVE_AND_FROZEN_RUNTIME_VERIFIED', source_head=BASE,
                frozen_runtime_files=101, runtime_manifest_sha256=RUNTIME_SHA,
                necessary_checkpoints=13, cloud_evaluation_reports=18,
                pilot_review_files=341, local_video_review_files=175, local_videos=10,
                video_archive_sha256=VIDEO_SHA, original_primary_sha256=PRIMARY,
                checkpoint_return_receipt_sha256=evidence['return_receipt_sha256'],
                full_cloud_traces_returned=False, new_ppo_updates=0,
                simulation_or_training_launched=False, network_used=False,
                manual_shutdown_confirmed=False, cloud_power_state='UNCONFIRMED',
                publication='Local validation record created before commit; user SSH push pending',
                stage09_policy_objective='UNMET_NO_ELIGIBLE_CANDIDATE')


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--verify-only', action='store_true', help='Check local evidence and documents without writing or committing')
    args = parser.parse_args()
    payload = json.loads(zlib.decompress(base64.b64decode(PAYLOAD)))
    require(REPO.is_dir() and git('rev-parse', '--show-toplevel') == str(REPO), 'Use the canonical laptop checkout')
    require(git('branch', '--show-current') == 'double-balance', 'Expected branch double-balance')
    require(git('remote', 'get-url', 'origin') == ORIGIN, 'Expected existing Git SSH origin; remote was not changed')
    require(git('remote', 'get-url', '--push', 'origin') == ORIGIN, 'Unexpected push URL')
    rows = payload['files']
    allowed = {r['path'] for r in rows} | {SCRIPT_REL, LOCAL_REL}
    require(len(allowed) == len(rows) + 2, 'Duplicate finalization targets')
    frozen = runtime()
    require(not (set(frozen) & allowed), 'Finalization would modify frozen runtime')
    staged = git_paths('diff', '--cached', '--name-only')
    require(staged <= allowed, 'Unrelated staged changes preserved; unstage those before retrying: ' + ', '.join(sorted(staged - allowed)))
    head = git('rev-parse', 'HEAD')
    already = head != BASE
    if already:
        require(git('log', '-1', '--format=%s') == MESSAGE and git('rev-parse', 'HEAD^') == BASE,
                'Unexpected source HEAD; nothing was changed')
        require(git_paths('diff', '--name-only', BASE, head) <= allowed, 'Unexpected changes in existing finalization commit')
    tagged = tagged_commit()
    require(tagged is None or (already and tagged == head), 'Conflicting completion tag preserved; no force update')
    desired = {}
    for row in rows:
        path = inside(REPO, row['path'])
        data = base64.b64decode(row['data'])
        require(hashlib.sha256(data).hexdigest() == row['sha256'], 'Embedded document hash mismatch')
        actual = sha(path) if path.is_file() else None
        permitted = [row['sha256']] if already else row['allowed_before'] + [row['sha256']]
        require(actual in permitted, 'Unexpected document edit preserved: ' + row['path'])
        desired[row['path']] = data
    script = Path(__file__).read_bytes()
    destination = inside(REPO, SCRIPT_REL)
    require(not destination.exists() or destination.read_bytes() == script, 'Existing finalizer script differs; preserved')
    desired[SCRIPT_REL] = script
    report = verify_evidence(payload['evidence'])
    local_path = inside(REPO, LOCAL_REL)
    if local_path.exists():
        old_report = read(local_path)
        require(old_report == report, 'Existing local validation report differs; preserved')
    desired[LOCAL_REL] = encoded(report)
    if already:
        for relative, data in desired.items():
            committed = subprocess.check_output(['git', '-C', str(REPO), 'show', 'HEAD:' + relative])
            require(committed == data, 'Existing finalization commit differs: ' + relative)
    if args.verify_only:
        print('Stage09Finalize=VERIFIED_ONLY; no changes made', flush=True)
        return
    if not already:
        # All artifact, source, index, tag and target checks finish before writes.
        backup = STAGE / 'finalization' / (datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%SZ') + '-' + uuid.uuid4().hex[:8])
        backup.mkdir(parents=True, exist_ok=False)
        for relative, data in desired.items():
            path = inside(REPO, relative)
            if path.is_file() and path.read_bytes() != data:
                atomic(backup / 'before' / relative, path.read_bytes())
            if not path.is_file() or path.read_bytes() != data:
                atomic(path, data)
        runtime()
        subprocess.run(['git', '-C', str(REPO), 'add', '--', *sorted(desired)], check=True)
        require(git_paths('diff', '--cached', '--name-only') <= allowed, 'Unexpected staged file; not committing')
        # Verify staged bytes, including documents that may have preexisting staged edits.
        for relative, data in desired.items():
            indexed = subprocess.check_output(['git', '-C', str(REPO), 'show', ':' + relative])
            require(indexed == data, 'Staged bytes differ: ' + relative)
        subprocess.run(['git', '-C', str(REPO), 'diff', '--cached', '--check'], check=True)
        subprocess.run(['git', '-C', str(REPO), 'commit', '-m', MESSAGE], check=True)
        head = git('rev-parse', 'HEAD')
        require(git('rev-parse', 'HEAD^') == BASE and git_paths('diff', '--name-only', BASE, head) <= allowed,
                'Unexpected post-commit changes; no tag created')
        for relative, data in desired.items():
            require(subprocess.check_output(['git', '-C', str(REPO), 'show', 'HEAD:' + relative]) == data,
                    'Committed document differs; no tag created: ' + relative)
    else:
        backup = STAGE / 'finalization' / ('already-committed-' + head[:12])
        backup.mkdir(parents=True, exist_ok=True)
    runtime()
    if tagged is None:
        subprocess.run(['git', '-C', str(REPO), 'tag', '-a', TAG, head, '-m',
                        'Stage 09: pilot reviewed; no eligible candidate; retain Stage 08 primary. Local archives verified; balance first.'], check=True)
    require(tagged_commit() == head, 'Annotated tag does not match local commit')
    receipt = dict(status='LOCAL_FINALIZATION_COMPLETE_SSH_PUSH_PENDING',
                   created_utc=datetime.now(timezone.utc).isoformat(), commit=head, annotated_tag=TAG,
                   branch='double-balance', changed_paths=sorted(git_paths('diff', '--name-only', BASE, head)),
                   new_ppo_updates=0, network_used=False, push_performed=False,
                   stage09_complete=False, policy_objective='UNMET_NO_ELIGIBLE_CANDIDATE',
                   manual_shutdown_confirmed=False, cloud_power_state='UNCONFIRMED')
    output = backup / 'finalization-receipt.json'
    atomic(output, encoded(receipt))
    print('Stage09Finalize=LOCAL_COMPLETE_SSH_PUSH_PENDING', flush=True)
    print('Stage09Commit=' + head, flush=True)
    print('Stage09AnnotatedTag=' + TAG, flush=True)
    print('Stage09FinalizationReceipt=' + str(output), flush=True)
    print('Stage09NewPPOUpdates=0', flush=True)
    print('Stage09CloudPower=UNCONFIRMED; if still running, shut down manually; preserve cloud data', flush=True)
    print('Stage09Next=Run on the laptop:', flush=True)
    print('cd /home/lx/microduck-double-balance/workspace')
    print('git push origin double-balance')
    print('git push origin stage-09-complete')
    print('Normal successful SSH push output is sufficient; do not repeat full remote verification.')


if __name__ == '__main__':
    try:
        main()
    except Exception as error:
        print('Stage09Finalize=STOPPED; ' + str(error), flush=True)
        raise SystemExit(1)
